const content = $input.first().json.output[0].content[0].text
const keyword = $('Code_아이디어선택').first().json['키워드'];
const category = $('Edit Fields').first().json['카테고리'];

// ═══ 기본 SEO 체크 ═══
const charCount = content.length;
const h1Count = (content.match(/^#\s/gm) || []).length;
const h2Count = (content.match(/^##\s/gm) || []).length;

const keywordMatches = (content.match(new RegExp(keyword, 'gi')) || []).length;
const density = ((keywordMatches * keyword.length) / charCount * 100).toFixed(2);

// ═══ 패션 블로그 특화 체크 ═══

// 1. 가격대 언급
const priceTerms = ['하이엔드', '미드', 'SPA', '합리적', '명품', '만원', '가격', '프리미엄'];
const hasPriceInfo = priceTerms.some(t => content.includes(t));
const priceCount = priceTerms.reduce((s, t) => s + (content.match(new RegExp(t, 'g')) || []).length, 0);

// 2. 스타일링 팁
const stylingTerms = ['스타일링', '코디', '매칭', '포인트', '팁', '추천', '연출', '활용'];
const stylingCount = stylingTerms.reduce((s, t) => s + (content.match(new RegExp(t, 'g')) || []).length, 0);

// 3. 체형/상황별 팁
const contextTerms = ['체형', '키', '상황', '오피스', '데일리', '데이트', '캐주얼', '통통', '슬림', '볼륨'];
const hasContextualTips = contextTerms.some(t => content.includes(t));

// 4. 이모지 수
const emojiCount = (content.match(/[\u{1F300}-\u{1F9FF}]|[\u{2600}-\u{26FF}]/gu) || []).length;

// 5. CTA
const ctaTerms = ['댓글', '저장', '공유', '팔로우', '알려주세요', '어떠세요', '좋아요'];
const hasCTA = ctaTerms.some(t => content.includes(t));

// 6. 체크리스트 존재
const hasChecklist = content.includes('✅') || content.includes('체크리스트') || content.includes('핵심 정리');

// ═══ 점수 계산 ═══
let score = 100;
const issues = [];
const wins = [];

// 기본 체크
if (charCount < 1500) { score -= 20; issues.push(`글자수 부족 (${charCount}자)`); }
else { wins.push(`✅ 충분한 분량 (${charCount}자)`); }

if (h2Count < 4) { score -= 15; issues.push(`섹션 부족 (H2 ${h2Count}개)`); }
else { wins.push(`✅ 체계적 구조 (${h2Count}개 섹션)`); }

if (density < 0.5) { score -= 10; issues.push(`키워드 밀도 낮음 (${density}%)`); }
if (density > 3) { score -= 10; issues.push(`키워드 남용 (${density}%)`); }

// 패션 특화 체크
if (!hasPriceInfo) { score -= 10; issues.push(`가격대 정보 없음`); }
else { wins.push(`✅ 가격대 정보 포함 (${priceCount}회)`); }

if (stylingCount < 5) { score -= 10; issues.push(`스타일링 팁 부족 (${stylingCount}회)`); }
else { wins.push(`✅ 풍부한 스타일링 팁 (${stylingCount}회)`); }

if (!hasContextualTips) { score -= 5; issues.push(`체형/상황별 팁 없음`); }
else { wins.push(`✅ 맞춤형 팁 포함`); }

if (emojiCount === 0) { score -= 5; issues.push(`이모지 없음 (패션 블로그 권장)`); }
else if (emojiCount > 20) { score -= 5; issues.push(`이모지 남용 (${emojiCount}개)`); }
else { wins.push(`✅ 적절한 이모지 (${emojiCount}개)`); }

if (!hasCTA) { score -= 5; issues.push(`독자 참여 CTA 없음`); }
else { wins.push(`✅ CTA 포함`); }

if (!hasChecklist) { score -= 5; issues.push(`핵심 정리 체크리스트 없음`); }
else { wins.push(`✅ 핵심 정리 포함`); }

// ═══ 등급 판정 ═══
let grade;
if (score >= 90) grade = 'S (발행 추천)';
else if (score >= 80) grade = 'A (소폭 수정 후 발행)';
else if (score >= 70) grade = 'B (수정 필요)';
else grade = 'C (재작성 필요)';

// ═══ H1 제목 추출 ═══
const titleMatch = content.match(/^#\s+(.+)$/m);
const title = titleMatch ? titleMatch[1] : '제목없음';

// ═══ Markdown → HTML 변환 ═══
let html = content
  .replace(/^#\s+(.+)$/gm, '<h1>$1</h1>')
  .replace(/^##\s+(.+)$/gm, '<h2>$1</h2>')
  .replace(/^###\s+(.+)$/gm, '<h3>$1</h3>')
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/\*(.+?)\*/g, '<em>$1</em>')
  .replace(/\[(.+?)\]\((.+?)\)/g, '<a href="$2">$1</a>')
  .replace(/^\-\s+(.+)$/gm, '<li>$1</li>')
  .split('\n\n')
  .map(p => {
    if (p.trim().startsWith('<')) return p;
    if (p.trim() === '') return '';
    return `<p>${p.trim()}</p>`;
  })
  .join('\n');

html = html.replace(/(<li>.*?<\/li>\n?)+/gs, m => `<ul>\n${m}</ul>\n`);

return [{
  json: {
    제목: title,
    카테고리: category,
    본문_MD: content,
    본문_HTML: html,
    글자수: charCount,
    H2개수: h2Count,
    키워드밀도: `${density}%`,
    가격정보: hasPriceInfo ? '✅' : '❌',
    스타일링팁수: stylingCount,
    체형상황별팁: hasContextualTips ? '✅' : '❌',
    이모지수: emojiCount,
    CTA여부: hasCTA ? '✅' : '❌',
    체크리스트: hasChecklist ? '✅' : '❌',
    품질점수: score,
    등급: grade,
    통과여부: score >= 70 ? '✅ 통과' : '❌ 재작성 필요',
    강점: wins,
    이슈: issues,
    작성일시: new Date().toISOString().slice(0, 19).replace('T', ' ')
  }
}];

const item = $json;
const category = item.카테고리;
const title = item.제목;

// ── 현재 시즌 판별 ──
const month = new Date().getMonth() + 1;
let seasonEn, mood;
if (month >= 3 && month <= 5) { seasonEn = 'spring'; mood = 'fresh, pastel, airy'; }
else if (month >= 6 && month <= 8) { seasonEn = 'summer'; mood = 'bright, breezy, vibrant'; }
else if (month >= 9 && month <= 11) { seasonEn = 'autumn'; mood = 'warm, earthy, cozy'; }
else { seasonEn = 'winter'; mood = 'rich, elegant, layered'; }

// ── 카테고리별 프롬프트 ──
const prompts = {
  '쇼핑가이드': `Flat lay photography of ${seasonEn} fashion items arranged on natural linen, editorial magazine style, ${mood}, overhead shot`,
  '스타일링': `Korean ${seasonEn} fashion editorial, young woman in stylish outfit, street photography style, natural pose, ${mood} atmosphere`,
  '트렌드': `Fashion mood board collage, ${seasonEn} color palette swatches, fabric textures, magazine tear sheet aesthetic, ${mood}`,
  '리뷰': `Luxury product photography on white marble surface, ${seasonEn} fashion accessory, studio lighting, ${mood}`,
  '룩북': `Full-body fashion editorial portrait, ${seasonEn} Korean style, soft natural window light, minimalist background, ${mood}`
};

const basePrompt = prompts[category] || prompts['스타일링'];
const fullPrompt = `${basePrompt}, topic: ${title}, 16:9 aspect ratio, NO text, NO logos, NO watermarks, magazine quality, aspirational and modern, high resolution`;

const categoryMap = { '트렌드': 3, '스타일링': 4, '리뷰': 5, '쇼핑가이드': 6, '룩북': 7 };

return [{
  json: {
    ...item,
    imagePrompt: fullPrompt,
    시즌_EN: seasonEn,
    카테고리ID: categoryMap[category] || 1
  }
}];

const month = new Date().getMonth() + 1;
const category = $json.카테고리;

let season, seasonKeywords, seasonEvents;
if (month >= 3 && month <= 5) {
  season = '봄';
  seasonKeywords = ['봄코디', '트렌치코트', '가디건', '파스텔', '꽃무늬'];
  seasonEvents = '벚꽃놀이, 입학, 신학기';
} else if (month >= 6 && month <= 8) {
  season = '여름';
  seasonKeywords = ['여름코디', '린넨', '원피스', '시어서커', '썸머니트'];
  seasonEvents = '바캉스, 페스티벌, 휴가';
} else if (month >= 9 && month <= 11) {
  season = '가을';
  seasonKeywords = ['가을코디', '니트', '자켓', '트위드', '레이어드'];
  seasonEvents = '추석, 단풍놀이, 캠핑';
} else {
  season = '겨울';
  seasonKeywords = ['겨울코디', '패딩', '코트', '부츠', '머플러'];
  seasonEvents = '크리스마스, 연말파티, 설날';
}

return [{
  json: {
    카테고리: category,
    시즌: season,
    시즌키워드: seasonKeywords,
    시즌이벤트: seasonEvents,
    생성일시: new Date().toISOString().slice(0, 19).replace('T', ' ')
  }
}];

const raw = $input.first().json.output[0].content[0].text;
let cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let ideas;
try {
  ideas = JSON.parse(cleaned);
} catch (e) {
  return [{ json: { 에러: '파싱실패', 원본: raw } }];
}

// 인기도 가장 높은 것 1개 선택
ideas.sort((a, b) => (b.예상인기도 || 0) - (a.예상인기도 || 0));
const best = ideas[0];

// 이전 시즌 정보 이어받기
const prev = $('Code_시즌판별').first().json;

return [{
  json: {
    주제: best.제목,
    키워드: best.키워드,
    타겟독자: best.타겟독자,
    카테고리: prev.카테고리,
    시즌: prev.시즌,
    톤: '친근하고 트렌디한, 언니가 알려주는 느낌',
    목표글자수: 2000,
    각도: best.각도,
    인기도: best.예상인기도,
    후보아이디어: ideas
  }
}];
